-- Areas and tables of the platform's own (adjustments T1; D94, D95; T79): `areas` and `tables`,
-- with the first connector's `places` becoming the till layer under them. Generated by
-- drizzle-kit, then edited by hand: row-level security, the `updated_at` triggers and the copy of
-- today's places into areas and tables. One transaction:
--   0. `places` and `barsy_venues` stop forcing row-level security on their owner for the length
--      of this transaction (the copy must see every row, also on an owner that does not bypass
--      RLS), and `places` stops touching `updated_at` (only `table_id` is written);
--   1. the two tables, their keys and indexes; three nullable columns on `places` (the till's hall
--      id and order, filled by the next read, and `table_id`);
--   2. the copy: for every place of a till venue that serves a venue of ours (`barsy_venues.
--      venue_id`), except places the till deleted, an area per hall name (a place with no hall goes
--      to an area called "Tables") and a table that KEEPS THE PLACE'S `tb_` ID, so links, the
--      print sheet and the table API stay valid; `name` is the manager's label, `number` the
--      till's; non-public and "--" placeholder places start hidden (D95); the QR token is copied,
--      so printed codes keep working, and `places.table_id` points back. Order keys are plain
--      ("a0", "a1", … then "b00" …), valid fractional keys core can insert between. Places of a
--      till venue that serves no venue get no table (there is no venue to own one);
--   3. row-level security and the triggers on the new tables; back to normal on the old ones.
-- `places.qr_token` and `places.label` stay for now: the code still reads them. The package that
-- moves routing and tokens to `tables` re-copies and drops them in its own migration.
-- Privileges come from src/table-access.ts (`pnpm db:roles`).

-- 0. Owner access for the copy; undone at step 3.
ALTER TABLE "restro"."places" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."places" DISABLE TRIGGER "places_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."barsy_venues" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint

-- 1. The tables.
CREATE TABLE "restro"."areas" (
	"id" text PRIMARY KEY NOT NULL,
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"name" text NOT NULL,
	"sort_key" text COLLATE "C" NOT NULL,
	"hidden" boolean DEFAULT false NOT NULL,
	"source_key" text,
	"archived_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "areas_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "areas_id_format" CHECK ("restro"."areas"."id" ~ '^ar_[0-9A-Za-z]+$'),
	CONSTRAINT "areas_name_length" CHECK (char_length("restro"."areas"."name") between 1 and 60 and "restro"."areas"."name" = btrim("restro"."areas"."name")),
	CONSTRAINT "areas_sort_key_format" CHECK ("restro"."areas"."sort_key" ~ '^[A-Za-z][0-9A-Za-z]*$'),
	CONSTRAINT "areas_source_key_length" CHECK ("restro"."areas"."source_key" is null or length("restro"."areas"."source_key") between 1 and 128)
);
--> statement-breakpoint
CREATE TABLE "restro"."tables" (
	"id" text PRIMARY KEY NOT NULL,
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"area_id" text NOT NULL,
	"name" text,
	"number" text,
	"sort_key" text COLLATE "C" NOT NULL,
	"hidden" boolean DEFAULT false NOT NULL,
	"qr_token" text,
	"archived_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "tables_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "tables_qr_token_unique" UNIQUE("qr_token"),
	CONSTRAINT "tables_id_format" CHECK ("restro"."tables"."id" ~ '^tb_[0-9A-Za-z]+$'),
	CONSTRAINT "tables_name_length" CHECK ("restro"."tables"."name" is null or (char_length("restro"."tables"."name") between 1 and 40 and "restro"."tables"."name" = btrim("restro"."tables"."name"))),
	CONSTRAINT "tables_number_length" CHECK ("restro"."tables"."number" is null or (char_length("restro"."tables"."number") between 1 and 40 and "restro"."tables"."number" = btrim("restro"."tables"."number"))),
	CONSTRAINT "tables_has_label" CHECK ("restro"."tables"."name" is not null or "restro"."tables"."number" is not null),
	CONSTRAINT "tables_sort_key_format" CHECK ("restro"."tables"."sort_key" ~ '^[A-Za-z][0-9A-Za-z]*$'),
	CONSTRAINT "tables_qr_token_format" CHECK ("restro"."tables"."qr_token" is null or "restro"."tables"."qr_token" ~ '^[A-Za-z0-9_-]{8,128}$')
);
--> statement-breakpoint
ALTER TABLE "restro"."places" ADD COLUMN "salon_id" text;--> statement-breakpoint
ALTER TABLE "restro"."places" ADD COLUMN "salon_weight" integer;--> statement-breakpoint
ALTER TABLE "restro"."places" ADD COLUMN "table_id" text;--> statement-breakpoint
ALTER TABLE "restro"."areas" ADD CONSTRAINT "areas_tenant_id_tenants_id_fk" FOREIGN KEY ("tenant_id") REFERENCES "restro"."tenants"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "restro"."areas" ADD CONSTRAINT "areas_venue_fk" FOREIGN KEY ("tenant_id","venue_id") REFERENCES "restro"."venues"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "restro"."tables" ADD CONSTRAINT "tables_tenant_id_tenants_id_fk" FOREIGN KEY ("tenant_id") REFERENCES "restro"."tenants"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "restro"."tables" ADD CONSTRAINT "tables_venue_fk" FOREIGN KEY ("tenant_id","venue_id") REFERENCES "restro"."venues"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "restro"."tables" ADD CONSTRAINT "tables_area_fk" FOREIGN KEY ("tenant_id","area_id") REFERENCES "restro"."areas"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "areas_venue_id_idx" ON "restro"."areas" USING btree ("venue_id","sort_key");--> statement-breakpoint
CREATE UNIQUE INDEX "areas_venue_id_source_key_unique" ON "restro"."areas" USING btree ("venue_id","source_key") WHERE "restro"."areas"."source_key" is not null;--> statement-breakpoint
CREATE INDEX "tables_area_id_idx" ON "restro"."tables" USING btree ("area_id","sort_key");--> statement-breakpoint
ALTER TABLE "restro"."places" ADD CONSTRAINT "places_table_fk" FOREIGN KEY ("tenant_id","table_id") REFERENCES "restro"."tables"("tenant_id","id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "restro"."places" ADD CONSTRAINT "places_table_id_unique" UNIQUE("table_id");--> statement-breakpoint

-- 2. Today's places become areas and tables (see the header).
DO $$
DECLARE
  alphabet constant text := '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
  till_venue record;
  hall record;
  place record;
  area_id text;
  area_count int;
  table_count int;
  random_bytes bytea;
  byte_value int;
  byte_position int;
BEGIN
  FOR till_venue IN
    SELECT bv.tenant_id, bv.integration_id, bv.bid, bv.venue_id
    FROM restro.barsy_venues bv
    WHERE bv.venue_id IS NOT NULL
    ORDER BY bv.venue_id
  LOOP
    area_count := 0;
    FOR hall IN
      SELECT coalesce(nullif(btrim(pl.salon_name), ''), 'Tables') AS name
      FROM restro.places pl
      WHERE pl.tenant_id = till_venue.tenant_id
        AND pl.integration_id = till_venue.integration_id
        AND pl.bid = till_venue.bid
        AND pl.state <> 'deleted'
      GROUP BY 1
      ORDER BY 1
    LOOP
      -- A fresh `ar_` id: 22 characters of base62 from random uuid bytes, by rejection sampling
      -- (a byte of 248 or more is dropped, so the 62 characters are equally likely; bytes 6 and 8
      -- hold the uuid's fixed version and variant bits and are skipped), like core's `newId`.
      area_id := '';
      WHILE length(area_id) < 22 LOOP
        random_bytes := uuid_send(gen_random_uuid());
        FOR byte_position IN 0..15 LOOP
          CONTINUE WHEN byte_position IN (6, 8);
          byte_value := get_byte(random_bytes, byte_position);
          IF byte_value < 248 AND length(area_id) < 22 THEN
            area_id := area_id || substr(alphabet, (byte_value % 62) + 1, 1);
          END IF;
        END LOOP;
      END LOOP;
      area_id := 'ar_' || area_id;
      INSERT INTO restro.areas (id, tenant_id, venue_id, name, sort_key)
      VALUES (
        area_id,
        till_venue.tenant_id,
        till_venue.venue_id,
        hall.name,
        CASE
          WHEN area_count < 62 THEN 'a' || substr(alphabet, area_count + 1, 1)
          ELSE 'b' || substr(alphabet, ((area_count - 62) / 62) + 1, 1)
                   || substr(alphabet, ((area_count - 62) % 62) + 1, 1)
        END
      );
      area_count := area_count + 1;

      table_count := 0;
      FOR place IN
        SELECT pl.id, pl.place_num, pl.label, pl.is_public, pl.qr_token
        FROM restro.places pl
        WHERE pl.tenant_id = till_venue.tenant_id
          AND pl.integration_id = till_venue.integration_id
          AND pl.bid = till_venue.bid
          AND pl.state <> 'deleted'
          AND coalesce(nullif(btrim(pl.salon_name), ''), 'Tables') = hall.name
        ORDER BY pl.place_num, pl.id
      LOOP
        INSERT INTO restro.tables (id, tenant_id, venue_id, area_id, name, number, sort_key, hidden, qr_token)
        VALUES (
          place.id,
          till_venue.tenant_id,
          till_venue.venue_id,
          area_id,
          nullif(btrim(place.label), ''),
          coalesce(
            nullif(btrim(place.place_num), ''),
            CASE WHEN nullif(btrim(place.label), '') IS NULL THEN '—' END
          ),
          CASE
            WHEN table_count < 62 THEN 'a' || substr(alphabet, table_count + 1, 1)
            ELSE 'b' || substr(alphabet, ((table_count - 62) / 62) + 1, 1)
                     || substr(alphabet, ((table_count - 62) % 62) + 1, 1)
          END,
          (NOT place.is_public) OR btrim(coalesce(place.place_num, '')) = '--',
          place.qr_token
        );
        UPDATE restro.places SET table_id = place.id WHERE id = place.id;
        table_count := table_count + 1;
      END LOOP;
    END LOOP;
  END LOOP;
END
$$;--> statement-breakpoint
DO $$
DECLARE
  uncopied bigint;
BEGIN
  SELECT count(*) INTO uncopied
  FROM restro.places pl
  JOIN restro.barsy_venues bv
    ON bv.tenant_id = pl.tenant_id AND bv.integration_id = pl.integration_id AND bv.bid = pl.bid
  WHERE bv.venue_id IS NOT NULL AND pl.state <> 'deleted' AND pl.table_id IS NULL;
  IF uncopied > 0 THEN
    RAISE EXCEPTION '0020_areas_tables: % places of served venues got no table; the migration owner must be able to read restro.places and restro.barsy_venues (superuser, BYPASSRLS, or the table owner)', uncopied;
  END IF;
END
$$;--> statement-breakpoint

-- 3. Row-level security and triggers on the new tables; the old ones back to normal.
SELECT restro.enable_tenant_rls('restro.areas');--> statement-breakpoint
SELECT restro.enable_tenant_rls('restro.tables');--> statement-breakpoint
CREATE TRIGGER areas_touch_updated_at BEFORE UPDATE ON restro.areas
  FOR EACH ROW EXECUTE FUNCTION restro.touch_updated_at();--> statement-breakpoint
CREATE TRIGGER tables_touch_updated_at BEFORE UPDATE ON restro.tables
  FOR EACH ROW EXECUTE FUNCTION restro.touch_updated_at();--> statement-breakpoint
ALTER TABLE "restro"."places" ENABLE TRIGGER "places_touch_updated_at";--> statement-breakpoint
ALTER TABLE "restro"."places" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "restro"."barsy_venues" FORCE ROW LEVEL SECURITY;
